/**
 * `pnpm data:types`: generates TypeScript models from the data schemas into
 * src/app/shared/models/generated (git-ignored), so schema, data and types can't drift.
 * Runs before build, test and typecheck.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile } from 'json-schema-to-typescript';

import { SCHEMA_DIR } from './registry';

export const OUT_DIR = 'src/app/shared/models/generated';
const BANNER =
  '/* Generated by scripts/data/generate-types.ts from src/data/schemas. Do not edit. */';

/** Writes one model per schema plus a barrel into `outDir` (default: the app's generated folder). */
export async function generateTypes(root: string, outDir = join(root, OUT_DIR)): Promise<string[]> {
  const schemaDir = join(root, SCHEMA_DIR);
  rmSync(outDir, { recursive: true, force: true });
  mkdirSync(outDir, { recursive: true });

  const names: string[] = [];
  const files = existsSync(schemaDir)
    ? readdirSync(schemaDir)
        .filter((f) => f.endsWith('.schema.json'))
        .sort()
    : [];
  for (const f of files) {
    const name = f.replace(/\.schema\.json$/, '');
    const schema = JSON.parse(readFileSync(join(schemaDir, f), 'utf8'));
    const ts = await compile(schema, schema.title ?? name, {
      bannerComment: BANNER,
      additionalProperties: false,
      cwd: schemaDir,
      style: { singleQuote: true, printWidth: 100, trailingComma: 'all' },
    });
    writeFileSync(join(outDir, `${name}.ts`), ts);
    names.push(name);
  }
  const index = names.length
    ? names.map((n) => `export type * from './${n}';`).join('\n')
    : 'export {};';
  writeFileSync(join(outDir, 'index.ts'), `${BANNER}\n${index}\n`);
  return names;
}

const isMain = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  generateTypes(process.cwd()).then(
    (names) =>
      console.log(`data:types: ${names.length ? names.join(', ') : 'no schemas yet'} → ${OUT_DIR}`),
    (e) => {
      console.error(`data:types failed: ${(e as Error).message}`);
      process.exit(1);
    },
  );
}
